    markers=[(r,c) for r in range(h) for c in range(w) if a[r][c]==1]
    # Vertical continuation: repeat the rectangle's column band beyond its top/bottom,
    # omitting columns marked in that exterior region.
    for r in range(r0):
        blocked={c for rr,c in markers if rr<r0}
        for c in range(c0,c1+1):
            if c not in blocked and a[r][c]==0: a[r][c]=2
    for r in range(r1+1,h):
        blocked={c for rr,c in markers if rr>r1}
        for c in range(c0,c1+1):
            if c not in blocked and a[r][c]==0: a[r][c]=2
    # Horizontal continuation on rows containing markers outside the rectangle.
    for r,c in markers:
        if r0<=r<=r1:
            if c<c0:
                for x in range(c1+1,w):
                    if a[r][x]==0: a[r][x]=2
            elif c>c1:
                for x in range(c0):
                    if a[r][x]==0: a[r][x]=2
    return a
