def transform(grid):
    a=[r[:] for r in grid]
    h,w=len(a),len(a[0])
    pts=[(r,c) for r in range(h) for c in range(w) if a[r][c]==2]
    r0=min(r for r,c in pts);r1=max(r for r,c in pts);c0=min(c for r,c in pts);c1=max(c for r,c in pts)
    # Perimeter rectangle bars: each marker outside the solid rectangle specifies
    # an aligned row or column that gets extended to the edge.
    marks=[(r,c) for r in range(h) for c in range(w) if a[r][c] not in (0,2)]
    for r,c in marks:
        if c<c0 and r0<=r<=r1:
            for x in range(c,c0):
                if a[r][x]==0:a[r][x]=2
        elif c>c1 and r0<=r<=r1:
            for x in range(c1+1,c+1):
                if a[r][x]==0:a[r][x]=2
        elif r<r0:
            for y in range(r+1,r0):
                if a[y][c]==0:a[y][c]=2
        elif r>r1:
            for y in range(r1+1,r):
                if a[y][c]==0:a[y][c]=2
    return a
